def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_my_D = sum(1 for a in my if a == 'D')
    last_my = my[-1]
    last_opp = opp[-1]

    recent_opp = opp[-10:] if n >= 10 else opp
    recent_opp_D = sum(1 for a in recent_opp if a == 'D')

    forgive_count = 0
    total_D_pairs = 0
    for i in range(n - 1):
        if my[i] == 'D':
            total_D_pairs += 1
            if opp[i+1] == 'C':
                forgive_count += 1
    forgive_rate = forgive_count / total_D_pairs if total_D_pairs > 0 else 0.0

    if total_D_pairs >= 3 and forgive_rate >= 0.6:
        return 'D'

    if last_opp == 'D':
        if recent_opp_D >= 4:
            return 'D'
        else:
            return 'C'
    else:
        if last_my == 'D':
            return 'D'
        else:
            if total_my_D == 0 and n >= 10:
                if all(a == 'C' for a in my[-10:]) and all(a == 'C' for a in opp[-10:]):
                    return 'D'
            return 'C'
